<?php
declare(strict_types=1);
namespace KMM\Core;
/** Fresh-install schema v5. Existing installations require a separate reviewed migration. */
final class ApplicationSchema {
    public static function statements():array {return [
        "CREATE TABLE IF NOT EXISTS application_tracks (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,job_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NULL,job_key CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '',status VARCHAR(25) NOT NULL DEFAULT 'consideration',revision INT UNSIGNED NOT NULL DEFAULT 1,archived_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE INDEX uniq_user_company_job(user_id,company_id,job_key),INDEX idx_track_user_status(user_id,status,updated_at),CONSTRAINT fk_track_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT fk_track_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_track_job FOREIGN KEY(job_id) REFERENCES jobs(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS application_events (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,track_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_kind VARCHAR(32) NOT NULL,title VARCHAR(180) NOT NULL,memo TEXT NULL,event_on DATE NULL,event_time TIME NULL,previous_status VARCHAR(25) NULL,new_status VARCHAR(25) NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_event_track_time(track_id,event_on,event_time),INDEX idx_event_eventtime(event_on),CONSTRAINT fk_event_track FOREIGN KEY(track_id) REFERENCES application_tracks(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS application_audit (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NOT NULL,track_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NULL,operation VARCHAR(40) NOT NULL,details_json TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_private_audit(actor_user_id,created_at),CONSTRAINT fk_app_audit_user FOREIGN KEY(actor_user_id) REFERENCES users(id),CONSTRAINT fk_app_audit_track FOREIGN KEY(track_id) REFERENCES application_tracks(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
    ];}
}
